 function setFont(size,weight=400){c.font=`${weight} ${size}px InvoiceSans, Arial, sans-serif`;c.textBaseline='alphabetic';c.fillStyle='#142744';}
 function wrapped(s,w,size,weight){setFont(size,weight);let out=[];for(const paragraph of String(s??'').split('\n')){let line='';for(const ch of paragraph){if(line&&c.measureText(line+ch).width>w){out.push(line);line=ch;}else line+=ch;}out.push(line);}return out;}
 function field(s,x,baseline,w,h,{size=normal,weight=400,align='left',name='Invoice field',wrap=false}={}){
  s=String(s??'');if(!s)return;
  let fontSize=size,lines=wrap?wrapped(s,w,size,weight):[s],lh=size*1.15;
  setFont(fontSize,weight);
  while(fontSize>4.2&&(Math.max(...lines.map(t=>c.measureText(t).width))>w||lines.length*lh>h)){fontSize-=.2;lh=fontSize*1.15;lines=wrap?wrapped(s,w,fontSize,weight):[s];setFont(fontSize,weight);}
  if(Math.max(...lines.map(t=>c.measureText(t).width))>w||lines.length*lh>h)issues.push(name);
  const max=Math.max(1,Math.floor(h/lh));c.save();c.beginPath();c.rect(align==='right'?x-w:align==='center'?x-w/2:x,baseline-size,w,h+size*.3);c.clip();c.textAlign=align;
  lines.slice(0,max).forEach((line,i)=>c.fillText(line,x,baseline+i*lh));c.restore();
 }
